// Meta webhook verification handshake (GET request).
// Meta calls: GET <webhook>?hub.mode=subscribe&hub.verify_token=...&hub.challenge=...
// We must echo hub.challenge with HTTP 200 if the token matches, otherwise 403.
return $input.all().map((item) => {
  const query = item.json.query || {};
  const expected = String((item.json.config || {}).verifyToken || '');
  const received = String(query['hub.verify_token'] || '');

  const ok =
    query['hub.mode'] === 'subscribe' &&
    expected.length > 0 &&
    received === expected;

  return {
    json: ok
      ? { statusCode: 200, body: String(query['hub.challenge'] ?? '') }
      : { statusCode: 403, body: 'Verification failed' },
  };
});

// Turns a raw WhatsApp Cloud API webhook payload into one item per incoming
// customer message. Status updates (sent/delivered/read), reactions and
// unknown events produce no items, so the workflow simply stops for them.

// Returns the text the AI should answer, or null to ignore the message.
function extractText(msg) {
  switch (msg.type) {
    case 'text':
      return msg.text?.body?.trim() || null;
    case 'interactive':
      return (
        msg.interactive?.button_reply?.title ||
        msg.interactive?.list_reply?.title ||
        null
      );
    case 'button':
      return msg.button?.text || null;
    case 'image':
    case 'video':
    case 'document': {
      const caption = msg[msg.type]?.caption?.trim();
      const note = `[The customer sent a ${msg.type}. You cannot view attachments.]`;
      return caption ? `${note} Caption: ${caption}` : note;
    }
    case 'audio':
    case 'sticker':
    case 'location':
    case 'contacts':
      return `[The customer sent a ${msg.type} message. You can only read text.]`;
    default:
      // reaction, system, unsupported, ...
      return null;
  }
}

const results = [];

for (const item of $input.all()) {
  const body = item.json.body || {};
  if (body.object !== 'whatsapp_business_account') continue;

  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      if (change.field !== 'messages') continue;
      const value = change.value || {};
      const contacts = value.contacts || [];

      for (const msg of value.messages || []) {
        const text = extractText(msg);
        if (!text) continue;

        const contact = contacts.find((c) => c.wa_id === msg.from) || contacts[0] || {};
        results.push({
          json: {
            messageId: msg.id,
            from: msg.from,
            name: contact.profile?.name || '',
            type: msg.type,
            text,
            timestamp: Number(msg.timestamp) || null,
            phoneNumberId: value.metadata?.phone_number_id || '',
            config: item.json.config || {},
          },
        });
      }
    }
  }
}

return results;

// Builds the request body for the selected AI provider (Claude or OpenAI).
// All settings come from the "Config" node, carried along in item.json.config.
const SUPPORTED = ['anthropic', 'openai'];
const MAX_INPUT_CHARS = 4000;

return $input.all().map((item) => {
  const msg = item.json;
  const cfg = msg.config || {};
  const provider = String(cfg.aiProvider || 'anthropic').toLowerCase().trim();

  if (!SUPPORTED.includes(provider)) {
    throw new Error(`Unknown aiProvider "${cfg.aiProvider}". Use "anthropic" or "openai" in the Config node.`);
  }

  const maxTokens = Number(cfg.maxTokens) > 0 ? Number(cfg.maxTokens) : 500;
  const system =
    String(cfg.systemPrompt || 'You are a helpful customer support assistant.') +
    (msg.name ? `\nThe customer's WhatsApp name is "${msg.name}".` : '') +
    '\nReply in the same language as the customer. Keep answers short and suitable for WhatsApp.';
  const userText = String(msg.text || '').slice(0, MAX_INPUT_CHARS);

  const body =
    provider === 'anthropic'
      ? {
          model: cfg.anthropicModel || 'claude-sonnet-5',
          max_tokens: maxTokens,
          system,
          messages: [{ role: 'user', content: userText }],
        }
      : {
          model: cfg.openaiModel || 'gpt-4o-mini',
          max_tokens: maxTokens,
          messages: [
            { role: 'system', content: system },
            { role: 'user', content: userText },
          ],
        };

  return {
    json: {
      provider,
      body,
      // Context needed after the AI call to send the reply back.
      context: {
        from: msg.from,
        messageId: msg.messageId,
        phoneNumberId: msg.phoneNumberId,
        graphApiVersion: cfg.graphApiVersion || 'v21.0',
        fallbackReply:
          cfg.fallbackReply || 'Sorry, I could not process your message right now. A team member will get back to you soon.',
      },
    },
  };
});

// Normalises the Claude / OpenAI response into a WhatsApp text message.
// If the AI call failed (the HTTP nodes continue on error), a friendly
// fallback reply is sent instead, and the error is kept in `aiError`.
const WHATSAPP_MAX_CHARS = 4096;

return $input.all().map((item, i) => {
  const res = item.json || {};
  const ctx = $('Build AI Request').itemMatching(i).json.context;

  let reply = '';
  let aiError = null;

  if (res.error) {
    aiError = typeof res.error === 'string' ? res.error : res.error.message || JSON.stringify(res.error);
  } else if (Array.isArray(res.content)) {
    // Anthropic Messages API
    reply = res.content
      .filter((block) => block.type === 'text')
      .map((block) => block.text)
      .join('\n')
      .trim();
  } else if (Array.isArray(res.choices)) {
    // OpenAI Chat Completions API
    reply = String(res.choices[0]?.message?.content || '').trim();
  }

  if (!reply && !aiError) aiError = 'Empty AI response';
  const usedFallback = !reply;
  if (usedFallback) reply = ctx.fallbackReply;
  if (reply.length > WHATSAPP_MAX_CHARS) reply = reply.slice(0, WHATSAPP_MAX_CHARS - 1) + '…';

  return {
    json: {
      to: ctx.from,
      phoneNumberId: ctx.phoneNumberId,
      graphApiVersion: ctx.graphApiVersion,
      replyText: reply,
      usedFallback,
      aiError,
      whatsappPayload: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: ctx.from,
        type: 'text',
        context: { message_id: ctx.messageId },
        text: { preview_url: false, body: reply },
      },
    },
  };
});
